events = [  # (초, 이벤트 ID, 계정, 출발지)
    (0, 4625, "admin", "10.0.0.5"), (5, 4625, "admin", "10.0.0.5"),
    (9, 4625, "admin", "10.0.0.5"), (14, 4625, "admin", "10.0.0.5"),
    (20, 4624, "admin", "10.0.0.5"), (30, 4624, "kim", "10.0.0.8"),
]
fails = {}
for t, eid, user, src in events:
    key = (user, src)
    if eid == 4625:
        fails.setdefault(key, []).append(t)
    elif eid == 4624:
        recent = [x for x in fails.get(key, []) if t - x <= 60]
        if len(recent) >= 3:
            print(f"ALERT {user} from {src}: {len(recent)} fails then success at t={t}")
        else:
            print(f"ok {user} from {src}")
